"""
Prompt模板定义

所有与LLM交互的提示词模板集中管理。
使用Jinja2风格的占位符，便于维护和多语言支持。
"""

from dataclasses import dataclass
from typing import Dict, Any


@dataclass(frozen=True)
class PromptTemplate:
    """提示词模板"""
    template: str

    def format(self, **kwargs: Any) -> str:
        """格式化模板"""
        return self.template.format(**kwargs)


# ==================== 记忆相关提示词 ====================

IMPORTANCE_RATING = PromptTemplate(
    template="""在1到10的范围内，1代表日常琐事（如刷牙、铺床），10代表极其重要或深刻的事件（如分手、大学录取），请评估以下记忆的可能重要性。

记忆: {memory_content}

请只返回一个1-10的数字作为评分。
评分:"""
)

MEMORY_QUERY = PromptTemplate(
    template="""{agent_name}正在思考关于"{topic}"的事情。

基于{agent_name}的背景：
{agent_description}

以下是{agent_name}相关的记忆：
{memories}

请总结{agent_name}关于{topic}的想法和感受。"""
)


# ==================== 反思相关提示词 ====================

REFLECTION_QUESTIONS = PromptTemplate(
    template="""根据以下{agent_name}最近的经历和记忆：

{recent_memories}

关于以上内容，我们能回答的{num_questions}个最重要的高层次问题是什么？

请只列出问题，每行一个："""
)

REFLECTION_INSIGHTS = PromptTemplate(
    template="""根据以下关于{agent_name}的陈述：

{relevant_memories}

从这些陈述中可以推断出哪{num_insights}条高层次洞察？

请使用以下格式返回洞察：
洞察内容 (因为 记忆编号1, 编号2, 编号3)

洞察："""
)


# ==================== 规划相关提示词 ====================

DAILY_PLAN = PromptTemplate(
    template="""{agent_name}的基本信息：
- 姓名：{agent_name}
- 年龄：{age}
- 性格特征：{traits}
- 当前状态：{lifestyle}
- 职业/身份：{occupation}

{agent_name}昨天的总结：
{yesterday_summary}

{agent_name}今天的日期是{current_date}。

请为{agent_name}规划今天的大致日程安排（{num_segments}个主要时段）。
从早上醒来开始，到晚上睡觉结束。

格式示例：
1) 7:00 AM - 起床，洗漱，吃早餐
2) 8:00 AM - 出门去工作
...

{agent_name}今天的日程安排："""
)

PLAN_DECOMPOSITION = PromptTemplate(
    template="""{agent_name}计划在{start_time}到{end_time}之间进行以下活动：
{activity}

请将这个活动分解为更具体的子任务（每个子任务5-15分钟）。

格式示例：
1) 9:00 AM: 打开电脑并登录 (5分钟)
2) 9:05 AM: 查看邮件 (10分钟)
...

子任务列表："""
)

REPLAN = PromptTemplate(
    template="""{agent_name}当前正在执行以下计划：
{current_plan}

但是，{agent_name}刚刚观察到：
{observation}

{agent_name}需要调整计划吗？如果需要，新计划是什么？

请回答"保持原计划"或提供新的计划："""
)


# ==================== 反应相关提示词 ====================

SHOULD_REACT = PromptTemplate(
    template="""{agent_name}的背景：
{agent_description}

{agent_name}当前正在：{current_action}

{agent_name}刚刚观察到：{observation}

{agent_name}对此有什么相关的记忆：
{relevant_memories}

{agent_name}应该对此做出反应吗？如果应该，{agent_name}会做什么？

请回答"继续当前活动"或描述{agent_name}的反应："""
)

GENERATE_REACTION = PromptTemplate(
    template="""{agent_name}决定对以下情况做出反应：
{observation}

{agent_name}的背景：{agent_description}
{agent_name}的当前心情/状态：{current_state}
相关记忆：{relevant_memories}

{agent_name}会具体做什么？请描述{agent_name}的行动："""
)


# ==================== 对话相关提示词 ====================

GENERATE_DIALOGUE = PromptTemplate(
    template="""{agent1_name}和{agent2_name}相遇了。

场景：{context}

{agent1_name}的背景：
{agent1_description}

{agent2_name}的背景：
{agent2_description}

{agent1_name}对{agent2_name}的印象和记忆：
{agent1_memories}

{agent2_name}对{agent1_name}的印象和记忆：
{agent2_memories}

请生成他们之间自然的对话（3-6轮）：

{agent1_name}:"""
)

CONTINUE_DIALOGUE = PromptTemplate(
    template="""以下是{agent1_name}和{agent2_name}之间的对话：

{dialogue_history}

{speaker_name}接下来会说什么？

{speaker_name}:"""
)


# ==================== 自我认知相关提示词 ====================

SELF_DESCRIPTION = PromptTemplate(
    template="""根据{agent_name}的记忆和经历：

{memories}

请用第一人称描述{agent_name}对自己的认知（性格、价值观、目标、关系等）：

我是{agent_name}，"""
)

DAILY_SUMMARY = PromptTemplate(
    template="""{agent_name}今天的经历：

{today_memories}

请用2-3句话总结{agent_name}今天的主要活动和感受："""
)


# ==================== 辅助函数 ====================

def get_all_prompts() -> Dict[str, PromptTemplate]:
    """获取所有提示词模板"""
    return {
        "importance_rating": IMPORTANCE_RATING,
        "memory_query": MEMORY_QUERY,
        "reflection_questions": REFLECTION_QUESTIONS,
        "reflection_insights": REFLECTION_INSIGHTS,
        "daily_plan": DAILY_PLAN,
        "plan_decomposition": PLAN_DECOMPOSITION,
        "replan": REPLAN,
        "should_react": SHOULD_REACT,
        "generate_reaction": GENERATE_REACTION,
        "generate_dialogue": GENERATE_DIALOGUE,
        "continue_dialogue": CONTINUE_DIALOGUE,
        "self_description": SELF_DESCRIPTION,
        "daily_summary": DAILY_SUMMARY,
    }
